	"demorequest/demorequest/view/RequestDetails.view.xml":'<mvc:View\n    controllerName="demorequest.demorequest.controller.RequestDetails"\n    xmlns:mvc="sap.ui.core.mvc"\n    xmlns:core="sap.ui.core"\n    displayBlock="true"\n    xmlns="sap.m"\n    xmlns:ui="sap.ui.table"\n    xmlns:smartFilterBar="sap.ui.comp.smartfilterbar"\n    xmlns:smartTable="sap.ui.comp.smarttable"\n    xmlns:html="http://www.w3.org/1999/xhtml"\n    xmlns:app="http://schemas.sap.com/sapui5/extension/sap.ui.core.CustomData/1"\n    height="100%"\n    xmlns:rowmodes="sap.ui.table.rowmodes"\n    xmlns:f="sap.ui.layout.form"\n><Page\n        id="page"\n        class="whiteBackgroundPage"\n        showHeader="false"\n    ><f:Form editable="true"><f:layout><f:ResponsiveGridLayout\n                    labelSpanXL="6"\n                    labelSpanL="6"\n                    labelSpanM="6"\n                    labelSpanS="12"\n                    adjustLabelSpan="false"\n                    emptySpanXL="0"\n                    emptySpanL="0"\n                    emptySpanM="0"\n                    emptySpanS="0"\n                    columnsXL="3"\n                    columnsL="3"\n                    columnsM="3"\n                /></f:layout><f:formContainers><f:FormContainer><f:formElements><f:FormElement><f:fields><Select\n                                    id="typeSelect"\n                                    width="350px"\n                                    change=".onTypeChange"\n                                    class="sapUiSmallMarginBegin"\n                                ><core:Item\n                                        key="Vendors"\n                                        text="{i18n>Vendors}"\n                                    /></Select></f:fields></f:FormElement></f:formElements></f:FormContainer><f:FormContainer><f:formElements><f:FormElement label="{i18n>TotalApprovalAmt}"><f:fields><Text\n                                    text="{\n                                        path: \'projectModel>/ApprovalAmount\',\n                                        type: \'sap.ui.model.type.Float\',\n                                        formatOptions: {\n                                            minFractionDigits: 2,\n                                            maxFractionDigits: 2\n                                        }\n                                    }"\n                                /></f:fields></f:FormElement></f:formElements></f:FormContainer></f:formContainers></f:Form><core:Fragment\n            fragmentName="demorequest.demorequest.fragment.Vendor"\n            type="XML"\n        /><footer><Toolbar><ToolbarSpacer /><Button\n                    type="Emphasized"\n                    text="{i18n>Submit}"\n                    press="onSubmitPress"\n                /><Button\n                    text="{i18n>Cancel}"\n                    type="Reject"\n                    press="onCancelPress"\n                /></Toolbar></footer></Page></mvc:View>'
